{
 "didatica": [
  {
   "campo": "resolucao.antes.formulas",
   "depois": [
    "probabilidade = casos favoráveis ÷ casos possíveis",
    "x% de y% = (x ÷ 100) × (y ÷ 100)"
   ],
   "motivo": "Evita fração escrita na linha e usa a forma dita em aula."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["internauta", "pessoa que usa a internet"],
    ["aleatoriamente", "sorteio em que todos têm a mesma chance"],
    ["60% são mulheres", "de cada 100 pessoas que acessam redes sociais, 60 são mulheres"],
    ["base da porcentagem", "o grupo que vale 100%; 90% são sobre todos os internautas e 60% só sobre quem acessa"],
    ["infográfico", "figura com desenhos e números que resume dados"]
   ],
   "motivo": "Explica 'base' e 'infográfico', palavras usadas na resolução e que o aluno pode não dominar."
  },
  {
   "campo": "resolucao.passos[1].porque",
   "depois": "O texto diz 'da quantidade de internautas que acessam redes sociais'. A base é quem acessa, não todos os internautas. Os bonecos mostram o mesmo: de 20 bonecos, 12 são mulheres e 8 são homens.",
   "motivo": "Frases mais curtas e sem ambiguidade."
  },
  {
   "campo": "resolucao.passos[3].conta",
   "depois": "40% de 90% = 0,4 × 0,9 = 0,36",
   "motivo": "Mantém a conta curta e sem mudar o valor."
  },
  {
   "campo": "resolucao.passos[4].conta",
   "depois": "0,36 = \\frac{36}{100} → B",
   "motivo": "Fração empilhada, como exige o padrão de matemática."
  },
  {
   "campo": "resolucao.quadro",
   "depois": [
    {"linha": "acessam: 90% dos internautas", "nota": "balão de cima do infográfico"},
    {"linha": "mulheres: 60% de quem acessa", "nota": "a base é o grupo que acessa"},
    {"linha": "homens: 100% − 60%", "nota": "entre os usuários, o que sobra"},
    {"linha": "homens: 40% de quem acessa", "nota": "100 − 60 = 40"},
    {"linha": "P = 40% de 90%", "nota": "homens que acessam, sobre todos"},
    {"linha": "P = 0,4 × 0,9", "nota": "porcentagem vira decimal"},
    {"linha": "P = 0,36", "nota": "4 × 9 = 36, duas casas decimais"},
    {"linha": "P = \\frac{36}{100}", "nota": "0,36 = 36 centésimos: letra B"}
   ],
   "motivo": "Separa a subtração e a conta, com notas claras e fração empilhada."
  },
  {
   "campo": "resolucao.erradas.D",
   "depois": "40/90 mistura duas bases: o 40 é porcentagem de quem acessa e o 90 é a porcentagem dos internautas que acessam. Quem marcou D esqueceu de trocar a base. O valor dá cerca de 44,4%, não 36%.",
   "motivo": "Diz o que faltou no raciocínio de quem marcou D."
  }
 ],
